pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, 1e30);
        vm.deal(address(this), amount);
        c.withdraw{value: amount}();
        vm.prank(address(this));
        c.withdraw();
        assertTrue(address(c).balance == 0);
    }
}
